import{_ as s,o as i,c as t,aA as e}from"./chunks/framework.BMzE2Z9R.js";const n="/assets/Snipaste_2024-07-26_18-03-28.B0q4K6KK.png",l="/assets/vscode_windows_preview_2024-07-27_1.D2DNHEme.png",o="/assets/vscode_windows_preview_2024-07-27_2.NBeDkxXj.png",b=JSON.parse('{"title":"开发工具与环境配置","description":"","frontmatter":{"comments":true},"headers":[],"relativePath":"about/contributing/tools.md","filePath":"about/contributing/tools.md","lastUpdated":1778399398000}'),p={name:"about/contributing/tools.md"};function h(d,a,r,c,k,g){return i(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="开发工具与环境配置" tabindex="-1">开发工具与环境配置 <a class="header-anchor" href="#开发工具与环境配置" aria-label="Permalink to &quot;开发工具与环境配置&quot;">​</a></h1><h2 id="推荐编辑工具" tabindex="-1">推荐编辑工具 <a class="header-anchor" href="#推荐编辑工具" aria-label="Permalink to &quot;推荐编辑工具&quot;">​</a></h2><ol><li><a href="https://code.visualstudio.com/" target="_blank" rel="noreferrer">VSCode</a></li><li><a href="https://obsidian.md/" target="_blank" rel="noreferrer">Obsidian</a></li><li><a href="https://typora.io/" target="_blank" rel="noreferrer">Typora</a></li><li>etc.</li></ol><p>（欢迎推荐更优秀的编辑工具）</p><h2 id="配置实时开发环境" tabindex="-1">配置实时开发环境 <a class="header-anchor" href="#配置实时开发环境" aria-label="Permalink to &quot;配置实时开发环境&quot;">​</a></h2><ul><li><a href="#linux">Linux</a></li><li><a href="#windows">Windows</a></li></ul><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h3><p>以下配置在Windows11 + WSL2 Ubuntu 24.02上经过测试。</p><h4 id="_0-git-clone" tabindex="-1">0. <code>git clone</code> <a class="header-anchor" href="#_0-git-clone" aria-label="Permalink to &quot;0. `git clone`&quot;">​</a></h4><p>移动到你要clone的目录后：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/Hailaylin/agi-society-cn.git</span></span></code></pre></div><blockquote><p>推荐clone的目录在WSL2的虚拟机内部路径，这样磁盘IO会很快。而跨文件系统（linux &lt;-&gt; Windows）的操作会很慢。</p></blockquote><h4 id="_1-安装-python-虚拟环境" tabindex="-1">1. 安装 Python 虚拟环境 <a class="header-anchor" href="#_1-安装-python-虚拟环境" aria-label="Permalink to &quot;1. 安装 Python 虚拟环境&quot;">​</a></h4><p>如果报错，则需要先安装python3，然后再执行上面的命令。apt源推荐换成清华源。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python3-full</span></span></code></pre></div><p>并且在主机创建虚拟环境</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agi-society-pyenv</span></span></code></pre></div><p>进入虚拟环境</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agi-society-pyenv/bin/activate</span></span></code></pre></div><p>然后你的终端会显示：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agi-society-pyenv</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">starlin@StarCloud:/mnt/d/NARS/000-AGI-Society.cn$</span></span></code></pre></div><p>则你已经入虚拟环境中。</p><h4 id="_2-启动实时预览" tabindex="-1">2. 启动实时预览 <a class="header-anchor" href="#_2-启动实时预览" aria-label="Permalink to &quot;2. 启动实时预览&quot;">​</a></h4><p>安装 mkdocs-material。网络不畅则需要设置pip国内镜像源。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mkdocs-material</span></span></code></pre></div><p>启动服务</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdocs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span></span></code></pre></div><h4 id="_3-vscode-实时预览" tabindex="-1">3. VSCode 实时预览 <a class="header-anchor" href="#_3-vscode-实时预览" aria-label="Permalink to &quot;3. VSCode 实时预览&quot;">​</a></h4><p>效果如下： <img src="'+n+'" alt="效果图" title="VSCode WSL MKDocs效果图"></p><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><p>以下配置在Windows11 + Python 3.11.4中测试通过。</p><p>步骤0同<a href="#0-git-clone">Linux</a>。</p><h4 id="_1-安装python" tabindex="-1">1. 安装Python <a class="header-anchor" href="#_1-安装python" aria-label="Permalink to &quot;1. 安装Python&quot;">​</a></h4><p>可在<a href="https://www.python.org/downloads/windows/" target="_blank" rel="noreferrer">官网下载</a>并安装Python，推荐选择尽量新的稳定版。</p><p>下载好安装程序后，根据安装程序指引安装即可。</p><h4 id="_2-安装扩展" tabindex="-1">2. 安装扩展 <a class="header-anchor" href="#_2-安装扩展" aria-label="Permalink to &quot;2. 安装扩展&quot;">​</a></h4><p>若Python环境已搭建完毕，此时可以使用<a href="https://pypi.org/" target="_blank" rel="noreferrer">pip</a>安装<a href="https://www.mkdocs.org/" target="_blank" rel="noreferrer">MKDocs</a>包<code>mkdocs-material</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mkdocs-material</span></span></code></pre></div><div class="callout" data-callout="tip"><div class="callout-title"><div class="callout-title-icon"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-flame"><path d="M8.5 14.5A2.5 2.5 0 0 0 11 12c0-1.38-.5-2-1-3-1.072-2.143-.224-4.054 2-6 .5 2.5 2 4.9 4 6.5 2 1.6 3 3.5 3 5.5a7 7 0 1 1-14 0c0-1.153.433-2.294 1-3a2.5 2.5 0 0 0 2.5 2.5z"></path></svg></div><div class="callout-title-inner">虚拟环境分隔运行</div></div><div class="callout-content"><p></p><p>若不希望在系统全局安装 <code>mkdocs-material</code> 包，可以创建一个虚拟环境，在虚拟环境中安装 <code>mkdocs-material</code>。</p><p>具体可参考<a href="#1-python">Linux对应小节</a>，或网络搜索关键词</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Python venv 创建虚拟环境</span></span></code></pre></div></div></div><h4 id="_3-开启实时预览" tabindex="-1">3. 开启实时预览 <a class="header-anchor" href="#_3-开启实时预览" aria-label="Permalink to &quot;3. 开启实时预览&quot;">​</a></h4><p>同<a href="#2">Linux对应小节</a>，在Git仓库目录下（如<code>...\\agi-society-cn\\</code>）运行如下命令：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdocs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span></span></code></pre></div><p>此时若观察到如下输出：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">INFO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [**:**:**] Browser connected: http://127.0.0.1:8000/[...]</span></span></code></pre></div><p>则说明启动成功。</p><p>此时打开浏览器，访问其中的链接<code>http://127.0.0.1:8000/[...]</code>即可看到实时预览。</p><p><img src="'+l+'" alt="VSCode"></p><p><img src="'+o+'" alt="浏览器"></p>',48)])])}const v=s(p,[["render",h]]);export{b as __pageData,v as default};
